package dev.eugheist.ttmodern;
final class ProtoclayAudit {
 static final net.neoforged.neoforge.registries.DeferredItem<SwordProbe> PROBE=ThaumicTinkererModern.ITEMS.register("audit_protoclay_sword",SwordProbe::new);
 static void init(){}
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT protoclay: "+label);}
 static final class SwordProbe extends net.minecraft.world.item.Item implements AdvancedTool {SwordProbe(){super(new Properties());}public String toolType(){return "sword";}}
 static void run(net.minecraft.server.MinecraftServer server){var level=server.overworld();var p=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"ClayAudit"));p.setPos(5.5,292,5.5);p.setXRot(90);var pos=new net.minecraft.core.BlockPos(5,290,5);var old=level.getBlockState(pos);var pick=new net.minecraft.world.item.ItemStack(AwakenedPick.ITEM.get());var shovel=new net.minecraft.world.item.ItemStack(AwakenedShovel.ITEM.get());var second=new net.minecraft.world.item.ItemStack(AwakenedShovel.ITEM.get());var clay=new net.minecraft.world.item.ItemStack(Protoclay.ITEM.get());AdvancedToolModes.change(pick);AdvancedToolModes.change(shovel);AdvancedToolModes.change(shovel);shovel.enchant(server.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getHolderOrThrow(net.minecraft.world.item.enchantment.Enchantments.SILK_TOUCH),1);p.getInventory().selected=0;p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,pick);p.getInventory().setItem(5,clay);p.getInventory().setItem(7,shovel);p.getInventory().setItem(8,second);
 try{level.setBlock(pos,net.minecraft.world.level.block.Blocks.SNOW_BLOCK.defaultBlockState(),2);p.swinging=false;Protoclay.ITEM.get().inventoryTick(clay,level,p,5,false);check(p.getMainHandItem()==pick,"no swing no swap");p.swinging=true;Protoclay.ITEM.get().inventoryTick(clay,level,p,5,false);check(p.getMainHandItem()==shovel&&p.getInventory().getItem(7)==pick&&p.getInventory().getItem(8)==second,"first matching tool swapped with selected slot");check(AdvancedToolModes.get(shovel)==2&&shovel.isEnchanted()&&AdvancedToolModes.get(pick)==1&&clay.getCount()==1,"modes/enchantments/stack identity and clay preserved");Protoclay.update(p);check(p.getMainHandItem()==shovel,"matching tool no swap");level.setBlock(pos,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),2);Protoclay.update(p);check(p.getMainHandItem()==pick&&p.getInventory().getItem(7)==shovel,"pick selected for actual stone ray");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(KamiTools.PICK.get()));Protoclay.update(p);check(p.getMainHandItem().is(KamiTools.PICK.get()),"ordinary tools excluded");var sword=new net.minecraft.world.item.ItemStack(PROBE.get());p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,sword);Protoclay.update(p);check(p.getMainHandItem()==sword,"advanced sword excluded");check(Protoclay.target(net.minecraft.world.level.block.Blocks.OAK_LOG.defaultBlockState()).equals("pick"),"original tool-not-required pick-first wood quirk");
 var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(r->r.key().equals("PROTOCLAY")).findFirst().orElseThrow();check(recipe.componentStacks().size()==4&&recipe.central().get()==net.minecraft.world.item.Items.CLAY_BALL&&recipe.instability()==4&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.MINE)==16&&recipe.aspects().getAmount(thaumcraft.api.aspects.Aspect.TOOL)==16,"original exact infusion");check(dev.eugheist.tc4modern.InfusionItemRecipes.match(recipe.componentStacks(),new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.CLAY_BALL),java.util.Set.of("PROTOCLAY"))==recipe,"native recipe match");var r=thaumcraft.api.research.ResearchCategories.getResearch("PROTOCLAY");check(r.displayColumn==12&&r.displayRow==17&&r.getPages().length==2&&java.util.Arrays.asList(r.parentsHidden).contains("ICHOR_SHOVEL_GEM"),"original research dependency and pages");System.out.println("TT PROTOCLAY AUDIT: ALL PASS (actual ray/swing inventory tick,first matching swap/identity/enchantments/modes,no consumption,ordinary/sword exclusions,original pick-first quirk,native infusion/research)");
 }finally{level.setBlock(pos,old,2);p.getInventory().clearContent();p.discard();}
 }
}
